import 'package:flutter/material.dart';
import '../services/krevzy_social_settings_service.dart';
class SoundSettingsScreen extends StatefulWidget { const SoundSettingsScreen({super.key}); @override State<SoundSettingsScreen> createState() => _SoundSettingsScreenState(); }
class _SoundSettingsScreenState extends State<SoundSettingsScreen> { bool stories = true, chats = true, favourite = true; String sound = 'KREVZY'; Future<void> setv(String k, bool v) async { setState(() { if (k == 'story_sounds') { stories = v; } if (k == 'chat_sounds') { chats = v; } if (k == 'favourite_person_sound') { favourite = v; } }); await KrevzySocialSettingsService.setValue(k, v); } Future<void> sets(String v) async { setState(() { sound = v; }); await KrevzySocialSettingsService.setValue('sound_type', v); } @override Widget build(BuildContext c) => Scaffold(appBar: AppBar(title: const Text('Sounds')), body: ListView(children: [SwitchListTile(title: const Text('Story sounds'), value: stories, onChanged: (v) => setv('story_sounds', v)), SwitchListTile(title: const Text('Chat sounds'), value: chats, onChanged: (v) => setv('chat_sounds', v)), SwitchListTile(title: const Text('Favourite person sound'), subtitle: const Text('Use favourite alert preference for selected people'), value: favourite, onChanged: (v) => setv('favourite_person_sound', v)), const Divider(), RadioGroup<String>(groupValue: sound, onChanged: (x) { if (x != null) { sets(x); } }, child: Column(children: ['KREVZY','Soft','Classic','Silent'].map((v) => RadioListTile<String>(title: Text(v), value: v)).toList()))])); }
